sql.where:
t_chat_buddy.is_delete = 0

        and t_chat_buddy.id = #{id}


        and t_chat_buddy.name = #{name}


        and t_chat_buddy.base64_icon = #{base64Icon}


        and t_chat_buddy.has_contact = #{hasContact}


        and t_chat_buddy.gender = #{gender}


        and t_chat_buddy.tags = #{tags}


        and t_chat_buddy.intimacy_level = #{intimacyLevel}


        and t_chat_buddy.gregorian_birthday = #{gregorianBirthday}


        and t_chat_buddy.lunar_birthday = #{lunarBirthday}


        and t_chat_buddy.notes = #{notes}


        and t_chat_buddy.sort = #{sort}


        and t_chat_buddy.bio = #{bio}


        and t_chat_buddy.avatar = #{avatar}


        and t_chat_buddy.photos = #{photos}


        and t_chat_buddy.favorite = #{favorite}


        and t_chat_buddy.disposition = #{disposition}

mapper.select:
select
    GROUP_CONCAT(tcbr.type_ids) as type_ids,

from t_chat_buddy tcb
LEFT JOIN t_chat_buddy_relations tcbr ON tcbr.to_id = tcb.id


        and tcb.id = #{dto.id}


        and tcb.name like CONCAT('%', #{dto.name}, '%')


        and coalesce(tcb.has_contact, 1) = #{dto.hasContact}


        and tcb.has_contact = #{dto.hasContact}


        and tcb.gender = #{dto.gender}


        and tcb.tags = #{dto.tags}


        and tcb.intimacy_level = #{dto.intimacyLevel}


        and tcb.notes like CONCAT('%', #{dto.notes}, '%')


        and tcb.sort = #{dto.sort}


group by tcb.id
order by tcb.sort

select count(*) from (
select tcb.id
from t_chat_buddy tcb
LEFT JOIN t_chat_buddy_relations tcbr ON tcbr.to_id = tcb.id


        and tcb.id = #{dto.id}


        and tcb.name like CONCAT('%', #{dto.name}, '%')


        and coalesce(tcb.has_contact, 1) = #{dto.hasContact}


        and tcb.has_contact = #{dto.hasContact}


        and tcb.gender = #{dto.gender}


        and tcb.tags = #{dto.tags}


        and tcb.intimacy_level = #{dto.intimacyLevel}


        and tcb.notes like CONCAT('%', #{dto.notes}, '%')


        and tcb.sort = #{dto.sort}


group by tcb.id) tmp_count
